-- spof-review: the new metric and controls are read from the worker's own review loop and the public log; if the publish to qnfo-audit fails the tick still completes (best effort, logged) and the fleet heartbeat watch sees the missing beat. Second path: GET https://markets.q08.org/api/track-record recomputes the chain directly.
-- CAUSE-MAPPED: pm_chain_ok maps to the existing cause key `measurement` in metric_breach_cause in this same file.
--
-- PM-CHARTER-1 research pass (2026-11-09, charter pillar personal). A later file than 2026-11-09-pm-charter.sql (already applied and not edited): it registers what the white paper
-- papers/pm-information-edge-2026-11-09 (served at https://markets.q08.org/whitepaper) added in q08-prediction-markets 1.6.0 and records the decision:
--   metric      pm_chain_ok (the hash chain over the append-only forecast log verifies) with a trigger;
--   controls    the domain pause, the forecast-log hash chain and the weekly parameter freeze, each with its alternate path and probe;
--   decision    the evidence-based design decision with a prediction for the calibration scorer.

INSERT OR IGNORE INTO metric_registry (metric, layer, kind, formula, source_of_truth, baseline, target, owner, disposition_actor, refresh_cadence, warning_band, kill_band, state, refresh_class) VALUES
 ('pm_chain_ok', 'operational', 'guard', '1 while the hash chain over the append-only forecast log verifies end to end (no row edited, removed or reordered), else 0; checked at most once an hour', 'q08-prediction-markets review loop (TRADES_DB pt_estimate_log); GET https://markets.q08.org/api/track-record recomputes it', '1 on 2026-11-09', '1', 'q08-prediction-markets', 'analytics_metric_triggers -> evaluateMetricTriggers (qnfo-fleet-control) files the breach', '*/5', '< 1', '< 1', 'NEW', 'runner');

INSERT OR IGNORE INTO metric_breach_cause (metric_key, cause_key, note) VALUES
 ('pm_chain_ok', 'measurement', 'PM-CHARTER-1: the forecast log integrity reading');

INSERT OR IGNORE INTO analytics_metric_triggers (metric_key, title, source_table, operator, threshold, priority, action, owner, queue_target, cooldown_hours, enabled, notes) VALUES
 ('pm_chain_ok', 'The prediction-market forecast log no longer verifies', 'metric_registry', 'lt', 1, 2,
  'Pillar personal (PM-CHARTER-1). The hash chain over q08-prediction-markets pt_estimate_log fails: a forecast row was edited, removed or reordered outside the worker, or the worker wrote a row with a wrong hash. GET https://markets.q08.org/api/track-record returns chain.bad_id, the first row that does not verify (how_to_verify says how to recompute it). The database triggers refuse UPDATE and DELETE on the log, so find who dropped them (read the D1 query history, pt_decision and the deploy ledger). Until the cause is fixed the forecasting evidence is not credible and graduation must not be read. Fix at the cause; never rewrite the log to make the chain verify: add a signed note row and keep the break visible.\ncode-task: repo=qnfo-workers path=q08-prediction-markets/worker.js\ncode-anchor: export async function verifyChain(rows) {',
  'qnfo-fleet-control', 'agent_issues', 24, 1, 'PM-CHARTER-1');

INSERT OR REPLACE INTO control_registry (control, location, kind, guards_against, critical_path, disposition, disposition_state, alternate_path, alternate_tested_at, evidence, reviewed_at) VALUES
 ('pm-domain-pause', 'q08-prediction-markets pt_control.domains_off (review loop)', 'pause', 'trading a domain (technology, crypto, macro, politics and so on) where the model is significantly worse than the price over 20 or more resolved forecasts (white paper hypothesis H6)', 0, 'keep', 'applied',
  'the switch-off expires after 14 days by itself so the domain is sampled again; other domains, exits, estimation of other domains and scoring continue; each switch-off is a pt_decision row with a rollback (DELETE FROM pt_control WHERE key = ''domains_off'')', '2026-11-09',
  'engine.test.mjs "tuneActions: weekly lock, bounded parameter moves, immediate domain switch-off"; tick.test.mjs "a switched-off domain is not estimated"', '2026-11-09T00:00:00Z'),
 ('pm-forecast-log-chain', 'q08-prediction-markets pt_estimate_log append-only triggers and hash chain', 'guard', 'the forecasting record being edited, deleted or reordered after the fact, which would make any claim of an edge uncheckable', 1, 'keep', 'applied',
  'none needed: the database refuses UPDATE and DELETE on the log with triggers, the chain is public at /api/track-record so anyone can verify it, and the metric pm_chain_ok (with a trigger) reports a break within the hour', '2026-11-09',
  'tick.test.mjs "the log refuses edits and deletes, and a tamper from outside is caught by the chain"; engine.test.mjs "the forecast log is a hash chain"', '2026-11-09T00:00:00Z'),
 ('pm-parameter-freeze', 'q08-prediction-markets pt_control.params_version and last_tune_at (review loop)', 'guard', 'tuning thresholds, recalibration or the blend weight while watching the score, which inflates the evidence that graduation is judged on (white paper section 4)', 0, 'keep', 'applied',
  'parameters change at most once a week and every change starts a new frozen sample; graduation counts only forecasts made under the current parameter version; the change and its rollback are logged in pt_decision', '2026-11-09',
  'tick.test.mjs "recalibration and domain switch-off change the parameters once, start a new sample, and are logged with rollbacks"', '2026-11-09T00:00:00Z');

INSERT OR IGNORE INTO control_alternate_probes (control, probe_sql, window_note, enabled) VALUES
 ('pm-domain-pause', 'SELECT ''ok'' AS expected, CASE WHEN EXISTS (SELECT 1 FROM fleet_heartbeat WHERE worker = ''q08-prediction-markets'' AND ts < strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-30 minutes'')) THEN ''the q08-prediction-markets heartbeat is older than 30 minutes, so the review loop that applies this control is not running'' WHEN NOT EXISTS (SELECT 1 FROM fleet_heartbeat WHERE worker = ''q08-prediction-markets'') AND (SELECT reviewed_at FROM control_registry WHERE control = ''pm-domain-pause'') < strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-6 hours'') THEN ''q08-prediction-markets never published a heartbeat since this control was registered'' ELSE ''ok'' END AS observed', '30 min: the domain switch-off is applied inside the review loop whose heartbeat is checked; its rule is replayed in engine.test.mjs (tuneActions)', 1),
 ('pm-forecast-log-chain', 'SELECT ''ok'' AS expected, CASE WHEN EXISTS (SELECT 1 FROM fleet_heartbeat WHERE worker = ''q08-prediction-markets'' AND ts < strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-30 minutes'')) THEN ''the q08-prediction-markets heartbeat is older than 30 minutes, so the review loop that applies this control is not running'' WHEN NOT EXISTS (SELECT 1 FROM fleet_heartbeat WHERE worker = ''q08-prediction-markets'') AND (SELECT reviewed_at FROM control_registry WHERE control = ''pm-forecast-log-chain'') < strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-6 hours'') THEN ''q08-prediction-markets never published a heartbeat since this control was registered'' WHEN COALESCE((SELECT CAST(last_value AS REAL) FROM metric_registry WHERE metric = ''pm_chain_ok''), 1) = 0 THEN ''the forecast log hash chain does not verify'' ELSE ''ok'' END AS observed', '30 min: the chain is verified at most hourly by the review loop and published as pm_chain_ok; a reading of 0 means a forecast row was changed outside the worker. The tamper case is replayed in tick.test.mjs', 1),
 ('pm-parameter-freeze', 'SELECT ''ok'' AS expected, CASE WHEN EXISTS (SELECT 1 FROM fleet_heartbeat WHERE worker = ''q08-prediction-markets'' AND ts < strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-30 minutes'')) THEN ''the q08-prediction-markets heartbeat is older than 30 minutes, so the review loop that applies this control is not running'' WHEN NOT EXISTS (SELECT 1 FROM fleet_heartbeat WHERE worker = ''q08-prediction-markets'') AND (SELECT reviewed_at FROM control_registry WHERE control = ''pm-parameter-freeze'') < strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-6 hours'') THEN ''q08-prediction-markets never published a heartbeat since this control was registered'' ELSE ''ok'' END AS observed', '30 min: the freeze is part of the same review loop whose heartbeat is checked; the weekly lock and the version bump are replayed in tick.test.mjs and engine.test.mjs', 1);

INSERT INTO decision_log (actor, assumption, action, evidence, outcome, blast_radius, rollback_path, capability_gain, predicted_outcome, reach_gain, surfaces_tested) VALUES
 ('claude-session', 'Published evidence shows no demonstrated general edge for language-model forecasters over a human crowd (Halawi 2024, Schoenegger 2024, ForecastBench, Metaculus benchmarks), none of it against market prices after costs; an edge, if any, lies in specific places (blending, structural mispricing, crowd bias, breadth, thin markets, domains where our sources lead) and published evaluations are easily inflated by leakage, tuning on the test set and selective memory',
  'Wrote the white paper papers/pm-information-edge-2026-11-09 (served at https://markets.q08.org/whitepaper) and implemented its recommendations R1 to R11 in q08-prediction-markets 1.6.0: first-forecast scoring with lead time, an append-only hash-chained public forecast log with a database-level append-only guard, weekly parameter tuning with frozen evaluation samples, logistic recalibration and a learned model/price blend from resolved outcomes, quarter-Kelly sizing, a spread filter, log loss beside Brier, and a per-domain proof with an automatic domain pause; filed structural arbitrage (issue 9106) and consistency probes (issue 9107)',
  'q08-prediction-markets 1.6.0: 60 worker tests including a tamper test that edits the log and is caught, synthetic worlds for the recalibration and blend fits, and a drift guard that fails when the paper, its HTML copy and the served page differ or when the paper states a number the charter does not; migrations/2026-11-09-pm-research.sql registers pm_chain_ok, three more controls with alternate-path probes and a trigger',
  'paper trading only; no live executor exists', 'the paper book and log of one worker and nine pm_* metric_registry rows; no real money, no other worker',
  'revert the PR; DELETE the rows named in the Rollback line of migrations/2026-11-09-pm-research.sql; DELETE FROM pt_control restores default parameters; the log is append-only by design and is left in place',
  'a public, tamper-evident, pre-registered forecasting record that makes any claimed edge checkable by outsiders', 'pm_chain_ok >= 1 within 24 h', 'a citable document and a verifiable track record for q08 forecasting work', 'worker tests, the paper rendered in a real browser at 375 px, the migration check and the control-probe, metric-registration and code-anchor suites');
